 <script>document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-ad-carousel]'),slides=[...root?.querySelectorAll('[data-ad-slide]')||[]],dots=[...root?.querySelectorAll('[data-ad-dot]')||[]],reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!root||slides.length<2)return;let active=0,timer,startX=0;const show=index=>{active=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('hidden',i!==active));dots.forEach((dot,i)=>{const mark=dot.firstElementChild;mark.classList.toggle('w-5',i===active);mark.classList.toggle('w-2',i!==active);mark.classList.toggle('bg-white',i===active);mark.classList.toggle('bg-white/60',i!==active)})};const stop=()=>clearInterval(timer),start=()=>{stop();if(!reduced)timer=setInterval(()=>show(active+1),5000)};root.querySelector('[data-ad-next]')?.addEventListener('click',()=>{show(active+1);start()});root.querySelector('[data-ad-prev]')?.addEventListener('click',()=>{show(active-1);start()});dots.forEach(dot=>dot.addEventListener('click',()=>{show(Number(dot.dataset.adDot));start()}));root.addEventListener('mouseenter',stop);root.addEventListener('mouseleave',start);root.addEventListener('pointerdown',event=>{startX=event.clientX;stop()});root.addEventListener('pointerup',event=>{const delta=event.clientX-startX;if(Math.abs(delta)>45)show(active+(delta<0?1:-1));start()});document.addEventListener('visibilitychange',()=>document.hidden?stop():start());start()});</script>


