<div id="consulta-pasaje" class="fixed inset-0 z-[10000] hidden place-items-center bg-emerald-950/70 p-4 backdrop-blur-sm" aria-hidden="true"><section class="relative w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl"><button class="ticket-modal-close absolute right-4 top-4 h-9 w-9 rounded-full bg-slate-100 text-xl">×</button><p class="text-xs font-black uppercase tracking-[.18em] text-emerald-700">Consulta rápida</p><h2 class="mt-2 text-2xl font-black text-emerald-950">Consulta tu boleto</h2><p class="mt-2 text-sm text-slate-500">Ingresa el DNI y el código de reserva o boleto.</p><form id="ticketLookupForm" class="mt-5 grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><input id="ticketLookupDocument" required placeholder="DNI o documento" class="rounded-xl border-slate-200"><input id="ticketLookupReference" required placeholder="Reserva RES-... o boleto BOL-..." class="rounded-xl border-slate-200"><button class="rounded-xl bg-amber-400 px-5 py-3 text-sm font-black">Buscar</button></form><div id="ticketLookupResult" class="mt-5"></div></section></div>



<script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('transportInput'),river=document.getElementById('riverResults'),air=document.getElementById('airResults'),tabs=[...document.querySelectorAll('[data-transport-tab]')],windows=[...document.querySelectorAll('[data-window]')],carousels=[...document.querySelectorAll('[data-departure-carousel]')],pages=new Map(),mode=()=>input?.value==='air'?'air':'river',activeWindow=()=>windows.find(tab=>tab.classList.contains('is-on'))?.dataset.window||'week',paintCounts=()=>{windows.forEach(tab=>{const total=Number(tab.dataset[mode()]||0),badge=tab.querySelector('b');if(!badge)return;badge.hidden=total<1;badge.textContent=total>0?String(total):''})},pageSize=()=>matchMedia('(max-width: 700px)').matches?1:3,paintCarousel=root=>{const want=activeWindow(),items=[...root.querySelectorAll('[data-departure-item]')],shown=items.filter(item=>want==='week'||item.dataset.today==='1'),size=pageSize(),pagesCount=Math.max(1,Math.ceil(shown.length/size));let page=Math.min(pages.get(root)||0,pagesCount-1);pages.set(root,page);items.forEach(item=>{item.hidden=true});shown.slice(page*size,page*size+size).forEach(item=>{item.hidden=false});const empty=root.querySelector('[data-departure-empty]');if(empty){empty.hidden=shown.length>0;empty.textContent=root.dataset[want==='today'?'emptyToday':'emptyWeek']||''}const nav=root.querySelector('[data-departure-nav]');if(nav)nav.hidden=shown.length<=size;const prev=root.querySelector('[data-departure-prev]'),next=root.querySelector('[data-departure-next]');if(prev)prev.disabled=page<=0;if(next)next.disabled=page>=pagesCount-1},paintAll=()=>{paintCounts();carousels.forEach(paintCarousel)};windows.forEach(tab=>tab.addEventListener('click',()=>{windows.forEach(item=>{const on=item===tab;item.classList.toggle('is-on',on);item.setAttribute('aria-selected',on?'true':'false')});carousels.forEach(root=>pages.set(root,0));paintAll()}));carousels.forEach(root=>{root.querySelector('[data-departure-prev]')?.addEventListener('click',()=>{pages.set(root,Math.max(0,(pages.get(root)||0)-1));paintCarousel(root)});root.querySelector('[data-departure-next]')?.addEventListener('click',()=>{pages.set(root,(pages.get(root)||0)+1);paintCarousel(root)})});addEventListener('resize',paintAll);show=type=>{input.value=type;river.classList.toggle('hidden',type==='air');air.classList.toggle('hidden',type==='river');tabs.forEach(t=>{const on=t.dataset.transportTab===type;t.classList.toggle('bg-white',on);t.classList.toggle('shadow-sm',on);t.classList.toggle('text-slate-500',!on);t.classList.toggle('text-emerald-800',on&&type==='river');t.classList.toggle('text-sky-800',on&&type==='air')});paintAll()};tabs.forEach(t=>t.onclick=()=>show(t.dataset.transportTab));show(input.value);document.getElementById('swapRoute').onclick=()=>{const a=document.getElementById('origin'),b=document.getElementById('destination'),origin=a.value,destination=b.value;a.closest('[data-public-select]').dispatchEvent(new CustomEvent('public-select:set',{detail:{value:destination}}));b.closest('[data-public-select]').dispatchEvent(new CustomEvent('public-select:set',{detail:{value:origin}}))};const modal=document.getElementById('consulta-pasaje'),close=document.querySelector('.ticket-modal-close'),result=document.getElementById('ticketLookupResult'),form=document.getElementById('ticketLookupForm');document.querySelectorAll('[data-ticket-modal]').forEach(b=>b.onclick=()=>{modal.classList.add('ny-modal-open');modal.setAttribute('aria-hidden','false')});close.onclick=()=>{modal.classList.remove('ny-modal-open');modal.setAttribute('aria-hidden','true')};modal.onclick=e=>{if(e.target===modal)close.click()};form.onsubmit=async e=>{e.preventDefault();result.textContent='Buscando pasaje…';try{const response=await fetch('{{route('travels.lookup')}}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'},body:JSON.stringify({document:document.getElementById('ticketLookupDocument').value.trim(),reference:document.getElementById('ticketLookupReference').value.trim()})}),data=await response.json();if(!response.ok)throw Error(data.message||'No se pudo consultar.');result.innerHTML=data.tickets.length?data.tickets.map(t=>`<article class="mt-3 grid grid-cols-[1fr_auto] gap-4 rounded-xl border p-4"><div><strong>${t.passenger}</strong><br><small>${t.route}</small><br><small>${t.departure} · ${t.vessel} · Asiento ${t.seat}</small></div><div><img class="h-20 w-20" src="${t.qr_url}"><a class="block text-xs font-bold text-emerald-700" href="${t.pdf_url}" target="_blank">Descargar PDF</a></div></article>`).join(''):'<p class="rounded-xl bg-amber-50 p-4 text-sm">No encontramos el boleto.</p>'}catch(error){result.innerHTML='<p class="rounded-xl bg-red-50 p-4 text-sm text-red-700">'+error.message+'</p>'}}});</script>
